	    TwinTemplate entity = new TwinTemplate();
            entity.setTwinTemplateId( event.getTwinTemplateId() );
            entity.setName( event.getName() );
            entity.setSchemaUri( event.getSchemaUri() );
            entity.setVersion( event.getVersion() );
	    
