	protected void emitFindAllTwinTemplate( TwinTemplate entity ) {
		LOGGER.info("handling emitFindAllTwinTemplate" );
		
	    queryUpdateEmitter.emit(FindAllTwinTemplateQuery.class,
	                            query -> true,
	                            entity);
	}

